"""Author original French material against the supplied outline. Never fetch FCC bodies."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
outline = json.loads((root / 'references/mvp_80_lessons.json').read_text(encoding='utf-8'))
entries = []

def q(body, example, prompt, choices, answer, why, hint):
    entries.append(dict(body=body, example=example, prompt=prompt, choices=choices, answer=answer, explanation=why, hints=[hint, why]))

def c(body, prompt, starter, solution, cases, hints):
    entries.append(dict(body=body, example=solution.split('\n')[0], prompt=prompt, starter=starter, solution=solution,
                        cases=[dict(label=label,args=args,expected=expected) for label,args,expected in cases], hints=hints,
                        explanation='Compare le résultat attendu et le résultat obtenu. Vérifie aussi les cas limites : valeur vide, zéro et dernière position.'))

# 01 — Fundamentals. Lessons also have a comprehension check; reading alone earns no XP.
q("JavaScript décrit des actions. Dans un navigateur, il peut réagir à un clic, calculer un total ou modifier le texte d'une page. HTML décrit la structure ; CSS règle l'apparence.\nUne instruction est une étape du programme. Exécuter du code signifie demander au moteur JavaScript de suivre ces étapes.", "const total = 4 + 3;", "Quelle action correspond à JavaScript ?", ['Structurer un titre HTML','Calculer le total du panier','Choisir la couleur en CSS'], '1', "JavaScript calcule et réagit aux événements. Le total vaut ici 7.", 'Cherche une action ou un calcul.')
q("Chaque valeur a un type. Un nombre sert au calcul ; une chaîne représente du texte ; un booléen vaut true ou false. Les guillemets changent le sens : 42 est un nombre, '42' est du texte.", "typeof 42; // 'number'", "Quel est le type de true ?", ['string','boolean','number'], '1', 'true et false sont les deux valeurs booléennes.', 'Une condition donne une réponse oui ou non.')
q("Une déclaration associe un nom à une valeur. const convient à une référence qui ne sera pas réassignée. let permet une nouvelle affectation. Les noms sont sensibles à la casse.", '_____ score = 10;', 'Complète avec le mot qui permet de réassigner score.', ['const','let','return'], 'let', 'let autorise score = 11 ; const interdit cette réaffectation.', 'La valeur pourra changer après la déclaration.')
c("Un programme peut garder une référence fixe et faire évoluer une autre variable. const ne veut pas dire que tous les objets deviennent immuables : cela interdit de remplacer la référence.", "Écris solve(start) : déclare une variable avec let, augmente-la de 1 et retourne sa valeur.", 'function solve(start) {\n  let score = start;\n  // Augmente score puis retourne-le.\n}', 'function solve(start) { let score = start; score += 1; return score; }', [('Départ à zéro',[0],1),('Score positif',[8],9),('Score négatif',[-2],-1)], ['Utilise score += 1.', 'Une fonction transmet son résultat avec return.'])
q("console.log affiche une valeur pour aider à comprendre le programme. Ce n'est pas la même chose que return : log produit un message, return transmet la réponse d'une fonction. Dans nos exercices, utilise return pour les résultats testés.", "console.log('Salut');\nconsole.log(2 + 5);", 'Quel est le deuxième message affiché ?', ['25','Salut','7'], '2', '2 + 5 additionne deux nombres : le résultat est 7.', 'Les guillemets indiqueraient du texte.')
c("Une variable conserve sa dernière valeur affectée. Lis les instructions dans leur ordre. Une affectation avec = remplace la valeur ; += ajoute à la valeur existante.", 'Corrige solve : après un bonus de 3, elle doit retourner start + 3, sans remplacer le score par 3.', 'function solve(start) {\n  let score = start;\n  score = 3; // Le bonus doit être ajouté.\n  return score;\n}', 'function solve(start) { let score = start; score += 3; return score; }', [('Bonus depuis zéro',[0],3),('Bonus depuis dix',[10],13),('Bonus depuis moins cinq',[-5],-2)], ['score = 3 oublie la valeur initiale.', 'Remplace = par += pour ajouter le bonus.'])
q("L'opérateur + additionne des nombres, mais concatène lorsqu'une chaîne participe à l'opération. Une conversion explicite avec Number rend l'intention claire. Évite de compter sur une conversion implicite inattendue.", "'4' + 2; // '42'\nNumber('4') + 2; // 6", "Comment obtenir le nombre 6 avec text = '4' ?", ['text + 2','Number(text) + 2','String(text) + 2'], '1', 'Number transforme le texte numérique en nombre avant le calcul.', 'Convertis le type avant de calculer.')
c("Un premier projet assemble plusieurs étapes simples : lire une entrée, calculer une réponse et la retourner. Une fonction pure ne modifie pas les données extérieures ; elle est facile à tester.", "Crée solve(name, points) qui retourne un objet { message, total } : message vaut 'Salut ' suivi de name et total vaut points + 5.", 'function solve(name, points) {\n  // Prépare le message et ajoute le bonus.\n}', "function solve(name, points) { return { message: 'Salut ' + name, total: points + 5 }; }", [('Préparer le message',['Lina',0],{'message':'Salut Lina','total':5}),('Ajouter un bonus',['Noé',10],{'message':'Salut Noé','total':15}),('Réunir les deux résultats',['Ada',-5],{'message':'Salut Ada','total':0})], ['Retourne un objet avec deux clés : message et total.', "Le texte du message commence par 'Salut ' avec un espace."])
# 02 — Strings and numbers
q("Une chaîne est une suite de caractères entourée de guillemets. Les guillemets ne font pas partie de sa valeur. On peut utiliser des apostrophes ou des guillemets doubles, en fermant avec le même caractère.", "const ville = 'Laval';\nville.length; // 5", "Combien de caractères contient 'code' ?", ['3','4','5'], '1', 'La propriété length compte les caractères de cette chaîne simple.', 'Compte c, o, d et e.')
q("Le premier caractère est à la position 0. L'accès texte[index] ne modifie pas la chaîne. Pour modifier un texte, on construit une nouvelle chaîne.", "const mot = 'code';\nmot[0]; // 'c'", "Que vaut 'code'[2] ?", ['o','d','e'], '1', "Les positions sont 0:c, 1:o, 2:d, 3:e.", 'Commence le compte à zéro.')
q("Concaténer veut dire réunir plusieurs textes. Ajoute explicitement un espace lorsqu'il doit apparaître. + ne rajoute aucun séparateur tout seul.", "const nom = 'Ada';\nconst texte = 'Bonjour ' _____ nom;", 'Quel opérateur réunit les textes ?', ['+','*','==='], '+', 'Le signe + concatène les chaînes.', 'Utilise le même opérateur que pour une addition.')
c("String(value) produit une représentation textuelle explicite. Elle fonctionne pour zéro et pour les nombres négatifs. La réponse '12' et le nombre 12 ont des types différents.", 'Écris solve(value) qui retourne le nombre reçu converti en chaîne.', 'function solve(value) {\n  // Retourne une chaîne.\n}', 'function solve(value) { return String(value); }', [('Nombre positif',[12],'12'),('Zéro',[0],'0'),('Nombre négatif',[-8],'-8')], ['La fonction globale String effectue la conversion.', 'Retourne String(value).'])
q("La multiplication et la division sont prioritaires sur l'addition. Les parenthèses imposent un ordre. Écris des expressions faciles à relire, même si le moteur connaît déjà les priorités.", '2 + 3 * 4; // 14\n(2 + 3) * 4; // 20', 'Que vaut (8 - 2) / 3 ?', ['2','6','4'], '0', 'Les parenthèses donnent 6, puis 6 / 3 donne 2.', 'Calcule la parenthèse en premier.')
c("Une moyenne se calcule en additionnant les valeurs, puis en divisant par leur nombre. Une parenthèse oubliée peut produire un résultat valide en syntaxe mais faux en logique.", 'Corrige solve(a, b) pour retourner la moyenne des deux nombres.', 'function solve(a, b) {\n  return a + b / 2;\n}', 'function solve(a, b) { return (a + b) / 2; }', [('Deux valeurs distinctes',[2,8],5),('Même valeur',[4,4],4),('Négatif et positif',[-4,4],0)], ['Additionne a et b avant de diviser.', 'Entoure a + b de parenthèses.'])
q("Un prix reçu sous forme de texte doit être converti avant de lui ajouter une taxe numérique. Une interpolation dans un gabarit de chaîne sert à présenter une valeur, pas à changer son type numérique.", "const prix = '10';", 'Quelle expression donne 12 comme nombre ?', ['prix + 2','Number(prix) + 2',"prix + '2'"], '1', 'Number(prix) vaut 10, donc le résultat numérique est 12.', 'Évite la concaténation.')
c("Les gabarits de chaînes utilisent des accents graves et ${expression}. Ils aident à combiner du texte et des valeurs calculées. La ponctuation et les espaces comptent dans une sortie textuelle.", "Écris solve(name, count) qui retourne exactement 'Ada a 3 points.' pour les entrées Ada et 3.", 'function solve(name, count) {\n  // Construis la phrase complète.\n}', 'function solve(name, count) { return `${name} a ${count} points.`; }', [('Insérer un nom',['Ada',3],'Ada a 3 points.'),('Insérer zéro',['Lina',0],'Lina a 0 points.'),('Garder la ponctuation',['Max',12],'Max a 12 points.')], ['Utilise un gabarit de chaîne ou la concaténation.', 'Ajoute le point final et les espaces autour de a.'])
# 03 — Conditions
q("Un booléen vaut true ou false. Une comparaison produit un booléen. Les conditions utilisent ce résultat pour choisir une branche du programme.", 'const majeur = 19 >= 18; // true', 'Quel résultat produit 5 < 2 ?', ['true','false','undefined'], '1', '5 est plus grand que 2 ; la comparaison est fausse.', 'Lis < comme est plus petit que.')
q("=== compare la valeur et le type sans convertir les opérandes. Deux valeurs qui s'affichent pareil peuvent avoir des types différents.", "7 === '7'; // false", "Que vaut 7 === 7 ?", ['true','false','7'], '0', 'Les deux opérandes sont le même nombre.', 'Même valeur et même type.')
q("== peut convertir des types avant de comparer. Pour éviter une conversion surprenante, préfère === quand les types doivent correspondre.", "const egal = 4 _____ '4'; // false", 'Complète avec la comparaison stricte.', ['==','===','='], '===', '=== ne convertit pas la chaîne en nombre.', 'Il faut trois signes égal.')
c("if exécute son bloc lorsque sa condition est vraie. return termine la fonction ; il peut donc séparer deux chemins de réponse.", 'Écris solve(age) qui retourne true si age est au moins 18, sinon false.', 'function solve(age) {\n  // Vérifie la limite de 18 ans.\n}', 'function solve(age) { if (age >= 18) return true; return false; }', [('Juste avant la limite',[17],False),('À la limite',[18],True),('Au-delà',[30],True)], ['Au moins signifie supérieur ou égal.', 'Utilise age >= 18.'])
q("else décrit le chemin suivi quand la condition du if est fausse. Une seule des deux branches est exécutée. Place les cas aux limites dans tes tests.", "if (score >= 10) {\n  resultat = 'validé';\n} else {\n  resultat = 'à revoir';\n}", 'Quelle branche est exécutée pour score = 9 ?', ['if','else','Les deux'], '1', '9 >= 10 est faux : la branche else est choisie.', 'Teste la condition avant de choisir le bloc.')
c("&& exige que les deux conditions soient vraies. || exige au moins une condition vraie. Le choix de cet opérateur fait souvent toute la différence.", 'Corrige solve(age, hasTicket) : une personne entre seulement si elle a au moins 18 ans ET un billet.', 'function solve(age, hasTicket) {\n  return age >= 18 || hasTicket;\n}', 'function solve(age, hasTicket) { return age >= 18 && hasTicket; }', [('Adulte avec billet',[18,True],True),('Adulte sans billet',[25,False],False),('Mineur avec billet',[16,True],False)], ['Les deux critères sont obligatoires.', 'Remplace || par &&.'])
q("= affecte une valeur ; === compare. Une affectation dans une condition peut modifier une variable et masquer une erreur logique.", 'let score = 3;\nif (score === 5) { /* bonus */ }', 'Comment comparer score au nombre 5 ?', ['score = 5','score === 5','score + 5'], '1', '=== compare sans changer score.', 'Cherche la comparaison stricte.')
c("Un calcul d'admissibilité doit exprimer toutes ses règles et tester les frontières. Sépare les conditions en variables si cela rend l'intention plus lisible.", 'Écris solve(age, score) : retourne true si age >= 16 ET score >= 60, sinon false.', 'function solve(age, score) {\n  // Vérifie les deux critères.\n}', 'function solve(age, score) { return age >= 16 && score >= 60; }', [('Deux seuils atteints',[16,60],True),('Score insuffisant',[20,59],False),('Âge insuffisant',[15,100],False)], ['Calcule deux comparaisons.', 'Combine les comparaisons avec &&.'])
# 04 — Functions
q("Une fonction regroupe des instructions sous un nom. On la déclare une fois puis on l'appelle. Les parenthèses de l'appel contiennent les arguments.", 'function doubler(n) { return n * 2; }\ndoubler(4); // 8', 'Quelle expression appelle la fonction ?', ['doubler','doubler(4)','function doubler'], '1', 'Les parenthèses réalisent un appel avec un argument.', 'Le nom seul désigne la fonction.')
q("Un paramètre est un nom local dans la déclaration. Un argument est une valeur fournie à l'appel. Chaque appel peut utiliser une valeur différente.", 'function carre(n) { return n * n; }\ncarre(3);', 'Quelle valeur reçoit n dans cet appel ?', ['9','3','n'], '1', 'L’argument 3 est affecté au paramètre n.', 'Lis la valeur entre parenthèses à l’appel.')
q("return transmet une valeur à l'appelant et termine l'exécution de la fonction. Sans return explicite, une fonction ordinaire retourne undefined.", 'function triple(n) {\n  _____ n * 3;\n}', 'Quel mot transmet le résultat ?', ['return','console','let'], 'return', 'return n * 3 renvoie le produit.', 'Afficher et retourner sont deux opérations différentes.')
c("Réutiliser une fonction évite de répéter un calcul. Une petite fonction peut appeler une autre fonction pour construire un résultat.", 'Écris solve(n) qui appelle une fonction doubler puis retourne deux fois le double de n.', 'function doubler(n) { return n * 2; }\nfunction solve(n) {\n  // Réutilise doubler.\n}', 'function doubler(n) { return n * 2; } function solve(n) { return doubler(doubler(n)); }', [('Valeur positive',[3],12),('Zéro',[0],0),('Valeur négative',[-2],-8)], ['Appliquer doubler deux fois multiplie par quatre.', 'Utilise doubler(doubler(n)).'])
q("Une variable déclarée avec let ou const dans un bloc reste dans ce bloc. Un paramètre appartient à sa fonction. Cela évite les collisions entre noms.", 'function lire() {\n  const secret = 8;\n  return secret;\n}', 'Où secret est-elle accessible ?', ['Partout','Dans lire seulement','Dans tous les fichiers'], '1', 'secret est locale au bloc de la fonction lire.', 'Regarde les accolades qui entourent la déclaration.')
c("Calculer une expression ne suffit pas à la retourner. Le résultat d'une fonction doit être explicitement transmis à l'appelant.", 'Répare solve(n) pour retourner le carré de n.', 'function solve(n) {\n  n * n;\n}', 'function solve(n) { return n * n; }', [('Carré positif',[4],16),('Carré négatif',[-3],9),('Carré de zéro',[0],0)], ['La multiplication est correcte.', 'Il manque return devant n * n.'])
q("console.log aide au diagnostic ; return fournit le résultat du calcul. Les tests de fonction comparent la valeur retournée.", 'function ajouter(a, b) { console.log(a + b); }', 'Que retourne cette fonction sans return ?', ['La somme','undefined','true'], '1', 'Un affichage ne remplace pas la valeur de retour.', 'Le moteur retourne une valeur par défaut.')
c("Un convertisseur isole une formule et son unité d'entrée. Pour Celsius vers Fahrenheit, multiplie par 9/5 puis ajoute 32. Teste des valeurs connues et le zéro.", 'Écris solve(celsius) qui retourne la température Fahrenheit, sans arrondi.', 'function solve(celsius) {\n  // Applique la formule.\n}', 'function solve(celsius) { return celsius * 9 / 5 + 32; }', [('Point de congélation',[0],32),('Point d’ébullition',[100],212),('Point commun aux échelles',[-40],-40)], ['La formule est celsius × 9 ÷ 5 + 32.', 'Respecte les unités et retourne le nombre.'])
# 05 — Arrays
q("Un tableau regroupe plusieurs valeurs dans un ordre. On le crée avec des crochets ; les éléments sont séparés par des virgules. Son premier index est 0.", "const fruits = ['pomme', 'banane', 'orange'];", 'Quelle écriture crée un tableau ?', ['{1, 2}','[1, 2]','(1, 2)'], '1', 'Les crochets créent un tableau JavaScript.', 'Cherche les crochets carrés.')
q("L'index repère une position, pas une valeur. Pour n éléments, les index vont de 0 à n - 1. Un index absent donne undefined.", "const villes = ['Laval', 'Québec', 'Montréal'];", 'Que vaut villes[1] ?', ['Laval','Québec','Montréal'], '1', 'Le deuxième élément est à l’index 1.', 'Commence à zéro.')
q("On remplace un élément en affectant sa position. Une variable const peut désigner un tableau dont les éléments changent ; on ne remplace pas la référence du tableau.", 'const valeurs = [4, 5];\nvaleurs[_____] = 9; // [4, 9]', 'Quel index remplace le deuxième élément ?', ['0','1','2'], '1', 'La deuxième position a l’index 1.', 'Un index de 2 désignerait un nouvel élément.')
c("push ajoute un élément à la fin. Pour garder l'entrée intacte, on peut créer une copie avec [...items], puis modifier cette copie.", 'Écris solve(items, value) qui retourne un nouveau tableau contenant items puis value, sans modifier items.', 'function solve(items, value) {\n  // Copie puis ajoute la valeur.\n}', 'function solve(items, value) { return [...items, value]; }', [('Ajouter à une liste',[[1,2],3],[1,2,3]),('Liste vide',[[],4],[4]),('Texte',[['a'],'b'],['a','b'])], ['La syntaxe [...items] copie les éléments.', 'Retourne [...items, value].'])
q("pop retire et retourne le dernier élément. shift retire le premier. Ces méthodes modifient le tableau ; il faut en tenir compte lorsqu'il est partagé.", 'const nombres = [2, 4, 6];\nconst dernier = nombres.pop();', 'Quelle est la valeur de dernier ?', ['2','6','[2, 4]'], '1', 'pop retourne l’élément retiré, ici 6.', 'Il s’agit du dernier élément.')
c("length compte les éléments. Le dernier index est length - 1. Confondre longueur et index provoque souvent un accès hors limites.", 'Corrige solve(items) pour retourner le dernier élément, ou null si le tableau est vide.', 'function solve(items) {\n  if (items.length === 0) return null;\n  return items[items.length];\n}', 'function solve(items) { if (items.length === 0) return null; return items[items.length - 1]; }', [('Trois éléments',[[4,5,6]],6),('Un seul élément',[[9]],9),('Aucun élément',[[]],None)], ['Le dernier index est inférieur à la longueur.', 'Soustrais 1 à items.length.'])
q("Un accès hors limites ne lance pas toujours une exception : un tableau retourne undefined pour une position absente. Cela peut ensuite contaminer un calcul.", 'const valeurs = [10, 20, 30];', 'Quel accès lit 30 ?', ['valeurs[3]','valeurs[2]','valeurs[-1]'], '1', 'Le troisième élément est à l’index 2.', 'La longueur vaut 3, le dernier index vaut 2.')
c("Une moyenne de tableau additionne les éléments puis divise par leur nombre. Le tableau vide doit avoir une règle explicite ; ici la moyenne est null.", 'Écris solve(numbers) qui retourne la moyenne, ou null pour un tableau vide.', 'function solve(numbers) {\n  // Additionne puis divise.\n}', 'function solve(numbers) { if (!numbers.length) return null; return numbers.reduce((s,n) => s+n, 0) / numbers.length; }', [('Calculer une somme',[[2,4,6]],4),('Gérer un élément',[[7]],7),('Gérer le vide',[[]],None)], ['Tu peux parcourir le tableau ou utiliser reduce.', 'Teste la longueur avant de diviser.'])
# 06 — Loops
q("Itérer signifie répéter une opération sur plusieurs éléments ou plusieurs étapes. Une boucle doit avoir une condition d'arrêt qui finit par devenir fausse.", 'for (let i = 0; i < 3; i++) { /* travail */ }', 'Combien de fois le corps est-il exécuté ?', ['2','3','4'], '1', 'i prend successivement 0, 1 et 2.', 'La valeur 3 est exclue par i < 3.')
q("La boucle for réunit initialisation, condition et mise à jour. La condition est vérifiée avant chaque tour.", 'for (let i = 1; i <= 3; i++) { /* ... */ }', 'Quelle est la dernière valeur de i dans le corps ?', ['2','3','4'], '1', '<= inclut la valeur 3.', 'Lis le signe égal dans la comparaison.')
q("while répète un bloc tant que sa condition est vraie. Le corps doit faire progresser un état vers l'arrêt.", 'let n = 0;\nwhile (n < 3) {\n  n_____;\n}', 'Complète pour incrémenter n.', ['++','--','==='], '++', '++ augmente n de 1 à chaque tour.', 'n doit se rapprocher de 3.')
c("for...of visite les valeurs d'un tableau dans leur ordre. Une variable accumulateur conserve un résultat entre les tours.", 'Écris solve(numbers) qui retourne la somme des éléments. Le tableau vide vaut 0.', 'function solve(numbers) {\n  let total = 0;\n  // Parcours les valeurs.\n}', 'function solve(numbers) { let total=0; for (const n of numbers) total+=n; return total; }', [('Plusieurs nombres',[[1,2,3]],6),('Vide',[[]],0),('Signes mélangés',[[-2,5]],3)], ['Ajoute chaque valeur à total.', 'N’oublie pas return total après la boucle.'])
q("break termine immédiatement la boucle courante. Il est utile lorsque l'objectif est atteint et que les tours suivants n'apportent rien.", 'for (const n of [1, 2, 3]) {\n  if (n === 2) break;\n  console.log(n);\n}', 'Quelle valeur est affichée ?', ['1 seulement','1 et 2','1, 2 et 3'], '0', 'La boucle s’arrête avant le log de 2.', 'Observe l’ordre du if et du log.')
c("Une condition d'arrêt incorrecte peut bloquer un programme. Nos exercices interrompent les calculs trop longs, mais la bonne correction est de rendre la progression explicite.", 'Répare solve(n), pour n entier positif ou nul, qui compte de 0 à n - 1 puis retourne n.', 'function solve(n) {\n  let i = 0;\n  while (i < n) { i--; }\n  return i;\n}', 'function solve(n) { let i=0; while(i<n) i++; return i; }', [('Plusieurs tours',[4],4),('Aucun tour',[0],0),('Un tour',[1],1)], ['i-- éloigne i de la limite.', 'Utilise i++ pour avancer vers n.'])
q("Pour parcourir les index d'un tableau, utilise i < length. i <= length ajoute un tour hors limites.", 'const a = [5, 6];\nfor (let i = 0; i < a.length; i++) { /* ... */ }', 'Quels index sont visités ?', ['0 et 1','0, 1 et 2','1 et 2'], '0', 'La longueur est 2 ; l’index 2 est exclu.', 'Le premier index est zéro.')
c("Filtrer garde seulement les éléments qui respectent une condition. Le résultat conserve l'ordre d'origine. Un élément exclu n'est pas remplacé par un trou.", 'Écris solve(numbers) qui retourne les valeurs strictement positives, dans le même ordre.', 'function solve(numbers) {\n  // Construis le tableau filtré.\n}', 'function solve(numbers) { return numbers.filter(n => n > 0); }', [('Filtrer les signes',[[-2,0,3,1]],[3,1]),('Rien à garder',[[-1,0]],[]),('Entrée vide',[[]],[])], ['Le zéro n’est pas strictement positif.', 'Utilise filter avec n > 0 ou une boucle et push.'])
# 07 — Data structures
q("Un tableau offre un accès direct par index. Une liste chaînée relie des nœuds ; pour atteindre un nœud éloigné, on suit les liens. Choisir une structure dépend des opérations fréquentes.", 'const node = { value: 3, next: null };', 'Quelle structure permet un accès direct par index ?', ['Liste chaînée','Tableau','Aucune'], '1', 'Un tableau peut lire son élément à une position sans suivre une chaîne de liens.', 'Pense à items[10].')
q("Une pile suit LIFO : dernier entré, premier sorti. Les opérations push et pop d'un tableau peuvent représenter une pile.", "const pile = [];\npile.push('A');\npile.push('B');", 'Que retourne pile.pop() ?', ['A','B','Les deux'], '1', 'B a été ajouté en dernier.', 'Imagine une pile d’assiettes.')
q("Une file suit FIFO : premier entré, premier sorti. Sur un petit tableau, push ajoute à la fin et shift retire au début. Pour de grandes files, on préférera éviter les décalages coûteux.", "const file = ['A', 'B'];\nfile._____(); // retire A", 'Quelle méthode retire le premier ?', ['pop','shift','push'], 'shift', 'shift enlève le premier élément.', 'pop enlèverait B.')
c("Un Set garde des valeurs uniques. Transformer un tableau en Set supprime les répétitions. L'ordre de première apparition est conservé lors de la conversion inverse.", 'Écris solve(values) qui retourne le tableau sans doublons dans l’ordre de première apparition.', 'function solve(values) {\n  // Utilise un ensemble.\n}', 'function solve(values) { return [...new Set(values)]; }', [('Doublons',[[2,1,2,3]],[2,1,3]),('Tout identique',[[4,4,4]],[4]),('Vide',[[]],[])], ['new Set(values) garde chaque valeur une fois.', 'Déplie le Set avec [...ensemble].'])
q("Une Map associe des clés à des valeurs. set écrit une association ; get lit sa valeur ; has vérifie l'existence de la clé.", "const scores = new Map();\nscores.set('Ada', 12);", "Comment lire le score d’Ada ?", ["scores['Ada']","scores.get('Ada')","scores.pop('Ada')"], '1', 'get consulte la valeur associée à une clé de Map.', 'Les méthodes de Map sont set, get et has.')
c("indexOf retourne le premier index d'une valeur, ou -1 si elle est absente. L'index 0 est un résultat valide et ne doit pas être confondu avec une absence.", 'Corrige solve(values, target) pour retourner true si target apparaît, y compris à l’index 0.', 'function solve(values, target) {\n  return values.indexOf(target) > 0;\n}', 'function solve(values, target) { return values.indexOf(target) >= 0; }', [('Premier élément',[[3,4],3],True),('Élément absent',[[3,4],9],False),('Deuxième élément',[[3,4],4],True)], ['0 est le premier index, pas une absence.', 'Compare l’index à -1 ou utilise >= 0.'])
q("Big O décrit comment le coût grandit avec la taille de l'entrée. Un parcours qui visite chaque élément une fois est linéaire : O(n). On ne mesure pas ici un temps exact en secondes.", 'for (const item of items) { /* coût constant */ }', 'Quelle complexité correspond à ce parcours ?', ['O(1)','O(n)','O(n²)'], '1', 'Doubler le nombre d’éléments double approximativement le travail.', 'Chaque élément est visité une fois.')
c("Un compteur de fréquences associe une valeur au nombre de ses apparitions. Une Map évite les conflits avec les propriétés spéciales d'un objet. Le résultat demandé ici est un tableau de paires.", 'Écris solve(words) : retourne les paires [mot, nombre], dans l’ordre de première apparition.', 'function solve(words) {\n  // Accumule les occurrences dans une Map.\n}', 'function solve(words) { const counts=new Map(); for(const w of words) counts.set(w,(counts.get(w)||0)+1); return [...counts]; }', [('Créer les clés',[['a','b']],[['a',1],['b',1]]),('Compter les répétitions',[['a','b','a']],[['a',2],['b',1]]),('Gérer le vide',[[]],[])], ['Lis le compteur existant ou zéro.', 'Ajoute 1 puis retourne [...counts].'])
# 08 — Algorithms
q("Avant de coder, précise les entrées, la sortie et les cas limites. Décompose ensuite le travail en étapes vérifiables. Un exemple ne remplace pas un contrat général.", 'Entrée : liste de nombres\nSortie : plus grand nombre ou null si vide', 'Quelle question faut-il trancher avant de coder ?', ['Le comportement pour une liste vide','La couleur du bouton','Le nombre de caractères du fichier'], '0', 'Le cas vide fait partie du contrat de la fonction.', 'Pense aux données d’entrée limites.')
q("Tracer un algorithme consiste à suivre ses variables étape par étape. C'est une méthode de diagnostic utile même sans exécuter le programme.", 'let total = 0;\nfor (const n of [2, 3]) total += n;', 'Quelle est la valeur finale de total ?', ['2','3','5'], '2', 'Le total passe de 0 à 2, puis de 2 à 5.', 'Additionne chaque élément une seule fois.')
q("Pour un maximum, compare chaque nouvelle valeur au meilleur résultat connu. Initialiser à zéro serait faux pour une liste entièrement négative.", 'const max = Math._____(...[-8, -2, -4]);', 'Quel nom appelle la fonction de maximum ?', ['min','max','round'], 'max', 'Math.max retourne la plus grande valeur.', 'On cherche -2, pas 0.')
c("Pour inverser une chaîne de caractères simples, décompose-la en caractères, inverse le tableau puis réunis les éléments. Array.from traite aussi les points de code comme les emoji simples.", 'Écris solve(text) qui retourne les caractères dans l’ordre inverse.', 'function solve(text) {\n  // Décompose, inverse et réunis.\n}', "function solve(text) { return Array.from(text).reverse().join(''); }", [('Texte simple',['code'],'edoc'),('Vide',[''],''),('Emoji simple',['a🙂'],'🙂a')], ['Array.from(text) crée le tableau de caractères.', "reverse inverse ; join('') réunit sans séparateur."])
q("Un Set permet de comparer le nombre d'éléments uniques à la longueur originale. Une taille plus petite signifie qu'au moins une valeur est répétée.", 'const values = [1, 2, 1];\nnew Set(values).size; // 2', 'Pourquoi sait-on qu’il existe un doublon ?', ['La taille du Set est inférieure à la longueur','Le premier élément vaut 1','Le tableau est trié'], '0', 'Trois éléments mais seulement deux valeurs uniques : une répétition existe.', 'Compare 2 et 3.')
c("Une recherche linéaire examine les éléments dans l'ordre. Elle retourne dès qu'elle trouve la cible. Renvoyer -1 trop tôt empêche d'examiner les éléments suivants.", 'Répare solve(values, target) pour retourner le premier index trouvé, ou -1.', 'function solve(values, target) {\n  for (let i=0; i<values.length; i++) {\n    if (values[i] === target) return i;\n    return -1;\n  }\n}', 'function solve(values, target) { for(let i=0;i<values.length;i++) if(values[i]===target) return i; return -1; }', [('Cible tardive',[[4,5,6],6],2),('Absence',[[4,5],7],-1),('Vide',[[],1],-1)], ['-1 est justifié après tout le parcours.', 'Déplace return -1 après la boucle.'])
q("Une recherche binaire élimine environ la moitié de l'intervalle à chaque étape. Elle exige des données triées selon le même ordre que les comparaisons.", 'const sorted = [2, 5, 9, 14, 20];', 'Quel prérequis est indispensable ?', ['Des données triées','Des nombres tous pairs','Un nombre pair d’éléments'], '0', 'Sans tri, éliminer une moitié peut éliminer la cible.', 'La comparaison au milieu doit permettre de choisir une moitié.')
c("Un algorithme de maximum doit traiter les nombres négatifs, le tableau vide et les doublons. Ces cas sont plus informatifs qu'un seul exemple positif.", 'Écris solve(values) qui retourne le maximum ou null si le tableau est vide.', 'function solve(values) {\n  // Définis un résultat initial correct.\n}', 'function solve(values) { return values.length ? Math.max(...values) : null; }', [('Comparer des valeurs',[[1,9,3]],9),('Ne pas initialiser à zéro',[[-7,-2,-8]],-2),('Gérer le vide',[[]],None)], ['Le premier élément peut servir de maximum initial.', 'Vérifie le vide avant de calculer.'])
# 09 — Git. JavaScript exercises model workflows; no shell execution is claimed.
q("Git conserve l'historique de fichiers sous forme de commits. Il permet de comparer des versions et de travailler sur des branches. Un dépôt distant partage l'historique, mais Git fonctionne aussi localement.", 'git status\ngit log --oneline', 'À quoi sert principalement Git ?', ['Versionner des fichiers','Exécuter JavaScript','Héberger automatiquement un site'], '0', 'Git suit les changements et leur historique.', 'Pense aux versions du travail.')
q("Un commit enregistre les changements préparés dans l'index. git add prépare des fichiers ; git commit enregistre cet état avec un message.", "git add app.js\ngit commit -m 'Corriger le total'", 'Quelle commande enregistre le commit ?', ['git status','git commit','git diff'], '1', 'commit crée un point d’historique local.', 'add prépare, commit enregistre.')
q("git diff présente les changements sous forme de lignes ajoutées et retirées. Lis le contexte pour comprendre leur effet, pas seulement le nombre de lignes.", 'git _____', 'Complète la commande qui montre les différences non indexées.', ['log','diff','push'], 'diff', 'git diff compare le travail non indexé à l’index.', 'Le mot signifie différence.')
c("Une branche est un nom mobile qui désigne un commit. Ici on modélise une commande Git sous forme de texte en JavaScript : aucun shell n'est exécuté.", "Écris solve(name) qui retourne la commande 'git switch -c ' suivie du nom reçu.", 'function solve(name) {\n  // Retourne une commande sous forme de texte.\n}', "function solve(name) { return 'git switch -c ' + name; }", [('Nom simple',['feature'],'git switch -c feature'),('Nom descriptif',['fix-total'],'git switch -c fix-total'),('Nom hiérarchique',['feat/api'],'git switch -c feat/api')], ['Le drapeau -c crée la branche.', 'Conserve un espace avant le nom.'])
q("Une pull request propose de fusionner une branche. Elle expose le diff, les échanges et les vérifications. L'ouverture d'une PR ne signifie pas que la fusion a eu lieu.", 'branche → pull request → revue → fusion', 'Que permet une pull request ?', ['Relire une modification avant fusion','Effacer tout l’historique','Remplacer les tests'], '0', 'Elle rend une modification visible pour discussion et validation.', 'La revue précède la fusion.')
c("Un conflit signale que Git ne peut pas combiner automatiquement certains changements. Il faut comprendre les deux versions puis décider du résultat. Les marqueurs de conflit ne doivent pas rester dans le fichier final.", 'Répare solve(text) : retourne true si le texte contient un marqueur de conflit <<<<<<<, sinon false.', "function solve(text) {\n  return text.includes('=======') && false;\n}", "function solve(text) { return text.includes('<<<<<<<'); }", [('Conflit présent',['<<<<<<< HEAD\na\n=======\nb\n>>>>>>> branch'],True),('Texte résolu',['const a = 1;'],False),('Vide',[''],False)], ['Le contrat demande de repérer <<<<<<<.', 'Utilise text.includes avec ce marqueur.'])
q("Une bonne revue vérifie le contrat, les cas limites et la lisibilité. Les tests automatiques apportent une preuve utile, sans remplacer la compréhension du changement.", 'Changement : division par items.length', 'Quel commentaire de revue est le plus utile ?', ['Que se passe-t-il si le tableau est vide ?','Le fichier est trop court','Ajoute un emoji au nom'], '0', 'Le tableau vide révèle un risque de division par zéro.', 'Cherche un défaut concret et vérifiable.')
c("Un workflow simple prépare, enregistre puis partage. L'intégration continue exécute les contrôles sur les changements proposés. Ce projet construit les étapes comme des données, sans lancer Git.", "Écris solve(file) qui retourne ['git add '+file, 'git commit -m " + '"Mettre à jour"' + "', 'git push'] dans cet ordre.", 'function solve(file) {\n  // Retourne les trois étapes.\n}', "function solve(file) { return ['git add '+file, 'git commit -m \"Mettre à jour\"', 'git push']; }", [('Préparer le fichier',['app.js'],['git add app.js','git commit -m "Mettre à jour"','git push']),('Garder l’ordre',['test.js'],['git add test.js','git commit -m "Mettre à jour"','git push']),('Chemin de fichier',['src/index.js'],['git add src/index.js','git commit -m "Mettre à jour"','git push'])], ['Le résultat est un tableau de trois chaînes.', 'add vient avant commit, puis push.'])
# 10 — HTTP, JSON, REST
q("Un client envoie une requête ; un serveur traite cette demande et renvoie une réponse. Une API définit les échanges permis. Le client ne doit pas décider seul des droits d'accès aux données.", 'client → requête HTTP → serveur\nclient ← réponse HTTP ← serveur', 'Qui renvoie la réponse HTTP ?', ['Le serveur','Le fichier CSS','Le clavier'], '0', 'Le serveur reçoit et traite la requête.', 'Suis les flèches du schéma.')
q("Une requête contient une méthode, un chemin, des en-têtes et parfois un corps. La méthode exprime l'intention de l'opération, pas son succès.", 'GET /api/lessons HTTP/1.1', 'Quelle est la méthode de cette requête ?', ['/api/lessons','GET','HTTP/1.1'], '1', 'GET est la méthode ; /api/lessons est le chemin.', 'Lis le premier mot.')
q("GET sert à lire une ressource. POST soumet généralement une nouvelle donnée ou déclenche une opération. Les deux nécessitent des règles d'autorisation adaptées.", "fetch('/api/attempts', { method: '_____', body: data });", 'Quelle méthode convient pour envoyer une tentative ?', ['GET','POST','READ'], 'POST', 'POST transmet une nouvelle tentative au serveur.', 'Une lecture ne doit pas créer de tentative.')
c("Un statut 2xx indique un succès HTTP. 4xx signale un problème lié à la requête et 5xx un problème côté serveur. Un succès HTTP ne garantit pas que le contenu métier attendu est correct.", 'Écris solve(status) qui retourne true pour les codes de 200 inclus à 300 exclus, sinon false.', 'function solve(status) {\n  // Vérifie les deux bornes.\n}', 'function solve(status) { return status >= 200 && status < 300; }', [('Succès',[200],True),('Fin de plage',[299],True),('Redirection',[300],False),('Erreur',[404],False)], ['Les deux bornes ont des inclusions différentes.', 'Combine status >= 200 et status < 300 avec &&.'])
q("JSON transporte des données : objets, tableaux, chaînes, nombres, booléens et null. Les clés d'objet sont entre guillemets doubles. JSON.parse transforme du texte JSON en valeur JavaScript.", 'const data = JSON.parse(\'{"score":12}\');\ndata.score; // 12', 'Quelle expression lit le score ?', ['data.score','data[12]','JSON.score'], '0', 'data est un objet dont la propriété score vaut 12.', 'On lit la propriété de l’objet retourné.')
c("Une ressource REST peut être représentée par un objet JSON. Il faut distinguer le texte brut de l'objet obtenu après analyse. Une chaîne n'expose pas directement les champs du JSON qu'elle contient.", 'Corrige solve(json) pour analyser le texte JSON puis retourner sa propriété name.', 'function solve(json) {\n  return json.name;\n}', 'function solve(json) { return JSON.parse(json).name; }', [('Objet simple',['{"name":"Ada"}'],'Ada'),('Autre valeur',['{"name":"Lina","id":2}'],'Lina'),('Chaîne vide comme valeur',['{"name":""}'],'')], ['Le paramètre est du texte JSON.', 'Utilise JSON.parse(json) avant de lire name.'])
q("CORS est un mécanisme du navigateur qui limite la lecture de réponses entre origines. Le serveur autorise les origines voulues avec ses en-têtes. CORS ne remplace ni l'authentification ni l'autorisation serveur.", 'Access-Control-Allow-Origin: https://app.example', 'Qui décide quelles origines peuvent lire la réponse dans le navigateur ?', ['Le serveur via ses en-têtes','Le texte du bouton','Le nom de la variable'], '0', 'Le navigateur applique les autorisations annoncées par le serveur.', 'Une origine comprend protocole, hôte et port.')
c("Une réponse API peut échouer ou contenir des données inattendues. Un petit adaptateur doit vérifier le statut avant de consommer la réponse, et définir un résultat pour les erreurs.", 'Écris solve(response) : si status est 2xx et body.items est un tableau, retourne sa longueur ; sinon retourne 0.', 'function solve(response) {\n  // Vérifie le statut puis la structure du corps.\n}', 'function solve(response) { return response.status >= 200 && response.status < 300 && Array.isArray(response.body?.items) ? response.body.items.length : 0; }', [('Lire une réponse valide',[{'status':200,'body':{'items':[1,2,3]}}],3),('Refuser une erreur',[{'status':500,'body':{'items':[1]}}],0),('Vérifier le schéma',[{'status':200,'body':{}}],0),('Gérer le vide',[{'status':204,'body':{'items':[]}}],0)], ['Valide d’abord la plage 2xx.', 'Utilise Array.isArray avant de lire length.'])

assert len(entries) == 80
lessons = []
for meta, content in zip(outline['lessons'], entries):
    item = {**meta, **content}
    item['license'] = 'LicenseRef-LiteCode-Original'
    item['attribution'] = 'Contenu original LiteCode ; aucune affiliation avec freeCodeCamp.'
    item['modifications'] = ['Explications, exercices, exemples et tests originaux en français ; référence thématique seulement.']
    if item['id'] in ['mvp-008','mvp-056']:
        item['title'] = 'Projet : profil de joueur' if item['id']=='mvp-008' else 'Projet : compteur de fréquences'
    if 'cases' in item:
        item['steps'] = [case['label'] for case in item['cases']]
    lessons.append(item)
target = root / 'curriculum/original.fr.json'
target.parent.mkdir(exist_ok=True)
target.write_text(json.dumps({'modules':outline['modules'],'lessons':lessons},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Authored',len(lessons),'original activities in',target)
